use crate::json_support::{json, JsonValue};

use crate::external::bindings::ExternalBindingToolOutcome;
use crate::external::lockfile::ExternalLockDriftKind;
use crate::external::status::{ExternalStatusReport, ExternalStatusState};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExternalReadinessReport {
    pub command: String,
    pub repo_name: String,
    pub ready: bool,
    pub blockers: Vec<ExternalReadinessBlocker>,
}

impl ExternalReadinessReport {
    pub fn to_json_value(&self) -> JsonValue {
        json!({
            "command": self.command,
            "repo_name": self.repo_name,
            "ready": self.ready,
            "blockers": self.blockers.iter().map(ExternalReadinessBlocker::to_json_value).collect::<Vec<_>>(),
            "summary": {
                "blockers": self.blockers.len(),
            },
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExternalReadinessBlocker {
    pub code: String,
    pub name: Option<String>,
    pub parent_path: Option<String>,
    pub path: Option<String>,
    pub message: String,
}

impl ExternalReadinessBlocker {
    pub fn to_json_value(&self) -> JsonValue {
        json!({
            "code": self.code,
            "name": self.name,
            "parent_path": self.parent_path,
            "path": self.path,
            "message": self.message,
        })
    }
}

pub fn build_external_readiness_report(status: &ExternalStatusReport) -> ExternalReadinessReport {
    let mut blockers = Vec::new();
    for drift in &status.lock_drifts {
        let code = match drift.kind {
            ExternalLockDriftKind::Missing => "external_lock_missing",
            ExternalLockDriftKind::Extra | ExternalLockDriftKind::Mismatch => "external_lock_drift",
        };
        blockers.push(ExternalReadinessBlocker {
            code: code.to_string(),
            name: Some(drift.name.clone()),
            parent_path: Some(drift.parent_path.clone()),
            path: Some(status.lockfile_path.clone()),
            message: drift.message.clone(),
        });
    }
    for entry in &status.externals {
        let code_and_message = match entry.state {
            ExternalStatusState::Linked => Some((
                "external_local_link_active",
                "local link override is active",
            )),
            ExternalStatusState::Missing => Some((
                "external_materialization_missing",
                "external materialization is missing",
            )),
            ExternalStatusState::Dirty => Some((
                "external_materialization_dirty",
                "external materialization is dirty or not generated by AIT",
            )),
            ExternalStatusState::Outdated => Some((
                "external_materialization_outdated",
                "external materialization does not match the lockfile snapshot",
            )),
            ExternalStatusState::Materialized => None,
        };
        if let Some((code, message)) = code_and_message {
            blockers.push(ExternalReadinessBlocker {
                code: code.to_string(),
                name: Some(entry.name.clone()),
                parent_path: Some(entry.parent_path.clone()),
                path: Some(entry.materialize_to.clone()),
                message: message.to_string(),
            });
        }
    }
    for check in &status.binding_checks {
        if !check.exists {
            blockers.push(ExternalReadinessBlocker {
                code: "external_binding_path_missing".to_string(),
                name: Some(check.name.clone()),
                parent_path: Some(check.parent_path.clone()),
                path: Some(check.full_path.clone()),
                message: format!(
                    "declared {} binding path is missing: {}",
                    check.language, check.path
                ),
            });
        }
        if !check.supported {
            blockers.push(ExternalReadinessBlocker {
                code: "external_binding_kind_unsupported".to_string(),
                name: Some(check.name.clone()),
                parent_path: Some(check.parent_path.clone()),
                path: Some(check.full_path.clone()),
                message: format!(
                    "declared {} binding kind {:?} is not supported",
                    check.language, check.kind
                ),
            });
        }
        if let ExternalBindingToolOutcome::Failed { message } = &check.toolchain {
            blockers.push(ExternalReadinessBlocker {
                code: "external_binding_toolchain_failed".to_string(),
                name: Some(check.name.clone()),
                parent_path: Some(check.parent_path.clone()),
                path: Some(check.full_path.clone()),
                message: message.clone(),
            });
        }
    }
    ExternalReadinessReport {
        command: "external readiness".to_string(),
        repo_name: status.repo_name.clone(),
        ready: blockers.is_empty(),
        blockers,
    }
}
